function H({registerIndicator:k,nulls:r}){k({id:"oa-pvo",name:"Percentage Volume Oscillator (PVO)",category:"Volume",placement:"pane",inputs:[{key:"fastPeriod",type:"number",label:"Fast Period",default:12,min:1,max:5e3,step:1},{key:"slowPeriod",type:"number",label:"Slow Period",default:26,min:1,max:5e3,step:1},{key:"signalPeriod",type:"number",label:"Signal Period",default:9,min:1,max:5e3,step:1}],plots:[{key:"pvo",type:"line",title:"PVO",style:{color:"#ffeb3b",lineWidth:2}},{key:"signal",type:"line",title:"Signal",style:{color:"#f23645",lineWidth:2}},{key:"histogram",type:"histogram",title:"Histogram",style:{color:"#2962ff",lineWidth:2}}],levels:()=>[{price:0,title:"Zero Line",color:"#787b86"}],calc(t,m){const c=Math.max(1,Math.floor(Number(m.fastPeriod)||12));let f=Math.max(1,Math.floor(Number(m.slowPeriod)||26));const A=Math.max(1,Math.floor(Number(m.signalPeriod)||9));f<=c&&(f=c+1);const u=2/(c+1),g=2/(f+1),h=2/(A+1),d=1-u,N=1-g,y=1-h,B=Math.max(d,N,y),w=new Array(t.length).fill(NaN),P=new Array(t.length).fill(NaN),b=new Array(t.length).fill(NaN);let l=!0,v=1,x=1,F=1,S=1,a=0,i=0,n=0;for(let e=0;e<t.length;e++){const M=t[e].volume,V=Number.isFinite(M)?M:0;a=u*(V-a)+a,i=g*(V-i)+i,l&&(v*=d,x*=N,F*=y,S*=B,l=S>1e-10);const E=l?1/(1-v):1,O=l?1/(1-x):1,W=l?1/(1-F):1,C=E*a,p=O*i,o=p!==0?(C-p)/p*100:0;n=h*(o-n)+n;const s=W*n;w[e]=Number.isFinite(o)?o:NaN,P[e]=Number.isFinite(s)?s:NaN,b[e]=Number.isFinite(o)&&Number.isFinite(s)?o-s:NaN}return{pvo:r(w),signal:r(P),histogram:r(b)}}})}export{H as default};
